    if($bytes.Length-ge3-and$bytes[0]-eq0xEF-and$bytes[1]-eq0xBB-and$bytes[2]-eq0xBF){return [Text.UTF8Encoding]::new($false,$false).GetString($bytes,3,$bytes.Length-3)}
