}
function Invoke-NativeBcdEdit([string[]]$Arguments){
    $exe=Join-Path $env:SystemRoot 'System32\bcdedit.exe';if(-not[IO.File]::Exists($exe)){throw 'WINDOWS_FIRMWARE_MANAGER_UNAVAILABLE'}
    if($null-eq$Arguments-or$Arguments.Count-eq0){throw 'WINDOWS_FIRMWARE_ARGUMENTS_DENIED'}
    foreach($argument in $Arguments){if([string]::IsNullOrWhiteSpace([string]$argument)-or[string]$argument-match'[\r\n\0]'){throw 'WINDOWS_FIRMWARE_ARGUMENTS_DENIED'}}
    $stdout=[IO.Path]::GetTempFileName();$stderr=[IO.Path]::GetTempFileName()
    try{
        try{$process=Start-Process -FilePath $exe -ArgumentList $Arguments -NoNewWindow -Wait -PassThru -RedirectStandardOutput $stdout -RedirectStandardError $stderr -ErrorAction Stop}catch{throw 'WINDOWS_FIRMWARE_MANAGER_START_FAILED'}
        $outputBytes=[IO.File]::ReadAllBytes($stdout);$errorBytes=[IO.File]::ReadAllBytes($stderr)
        $output=Read-NativeRedirectedText $stdout;$error=Read-NativeRedirectedText $stderr
        if($outputBytes.Length-gt1048576-or$errorBytes.Length-gt65536){throw 'WINDOWS_FIRMWARE_MANAGER_OUTPUT_CAP_EXCEEDED'}
        return [pscustomobject]@{ExitCode=[int]$process.ExitCode;Output=[string]$output;Error=[string]$error;OutputBytesBase64=[Convert]::ToBase64String($outputBytes);Command=($exe+' '+($Arguments-join' '))}
    }finally{foreach($file in @($stdout,$stderr)){try{if([IO.File]::Exists($file)){[IO.File]::Delete($file)}}catch{}}}
}
function Get-NativeWindowsBootManagerPath {
    # Radical compatibility path: use the exact direct BCDEdit invocation that
    # succeeds interactively on Windows PowerShell 5.1, then perform only exact
    # case-insensitive token checks. No regex, no line parser, no redirected IO.
    $exe=Join-Path $env:SystemRoot 'System32\bcdedit.exe'
    if(-not[IO.File]::Exists($exe)){throw 'WINDOWS_FIRMWARE_MANAGER_UNAVAILABLE'}
    try{
        $captured=@(& $exe /enum '{bootmgr}' 2>&1)
        $exitCode=[int]$LASTEXITCODE
    }catch{
        $script:resolverDiagnostic=('Command='+$exe+' /enum {bootmgr}; DirectInvocationException='+([string]$_.Exception.Message -replace'[\r\n\t]+',' '))
        throw 'WINDOWS_BOOTMGR_QUERY_FAILED'
    }
    $text=(($captured|ForEach-Object{[string]$_}) -join [Environment]::NewLine)
    $compact=($text-replace'[\r\n\t]+',' ').Trim();if($compact.Length-gt700){$compact=$compact.Substring(0,700)}
    $script:resolverDiagnostic=('Command='+$exe+' /enum {bootmgr}; ExitCode='+$exitCode+'; Output='+$compact+'; CaptureMode=DirectExactToken')
    if($exitCode-ne0){throw 'WINDOWS_BOOTMGR_QUERY_FAILED'}
    $native='\EFI\Microsoft\Boot\bootmgfw.efi'
    $compat='\EFI\SecretoBoot\refind_x64.efi'
    $normalized=$text.ToUpperInvariant()
    if($normalized.Contains($native.ToUpperInvariant())){$script:resolverDiagnostic+='; ExactPath=NativeWindows';return $native}
    if($normalized.Contains($compat.ToUpperInvariant())){$script:resolverDiagnostic+='; ExactPath=SecretoBootCompatibility';return $compat}
    throw 'WINDOWS_BOOTMGR_PATH_MISSING'
}
function Set-NativeWindowsBootManagerPath([string]$Path){
    # Write through the same direct BCDEdit process model and verify by an
    # independent fresh exact-token readback. Only the two approved EFI paths
    # are accepted. Microsoft bootmgfw.efi itself is never touched.
    $native='\EFI\Microsoft\Boot\bootmgfw.efi';$compat='\EFI\SecretoBoot\refind_x64.efi'
    if(-not([string]::Equals($Path,$native,[StringComparison]::OrdinalIgnoreCase))-and-not([string]::Equals($Path,$compat,[StringComparison]::OrdinalIgnoreCase))){throw 'WINDOWS_BOOTMGR_PATH_DENIED'}
    $exe=Join-Path $env:SystemRoot 'System32\bcdedit.exe'
    if(-not[IO.File]::Exists($exe)){throw 'WINDOWS_FIRMWARE_MANAGER_UNAVAILABLE'}
    try{
        $captured=@(& $exe /set '{bootmgr}' path $Path 2>&1)
        $exitCode=[int]$LASTEXITCODE
    }catch{
        $script:resolverDiagnostic=('Command='+$exe+' /set {bootmgr} path '+$Path+'; DirectInvocationException='+([string]$_.Exception.Message -replace'[\r\n\t]+',' '))
        throw 'WINDOWS_BOOTMGR_PATH_WRITE_FAILED'
    }
    $text=(($captured|ForEach-Object{[string]$_}) -join [Environment]::NewLine)
    $compact=($text-replace'[\r\n\t]+',' ').Trim();if($compact.Length-gt500){$compact=$compact.Substring(0,500)}
    $script:resolverDiagnostic=('Command='+$exe+' /set {bootmgr} path '+$Path+'; ExitCode='+$exitCode+'; Output='+$compact+'; CaptureMode=DirectPowerShellWrite')
    if($exitCode-ne0){throw 'WINDOWS_BOOTMGR_PATH_WRITE_DENIED'}
    $readback=Get-NativeWindowsBootManagerPath
    if(-not([string]::Equals([string]$readback,[string]$Path,[StringComparison]::OrdinalIgnoreCase))){throw 'WINDOWS_BOOTMGR_PATH_READBACK_MISMATCH'}
    return $readback
}

