function Get-CurrentBootTargetSnapshot([object]$Core,[object]$TargetAccess){
    $entries=@($Core.BootEntries);if($entries.Count-lt1-or$entries.Count-gt4096){throw 'CURRENT_BOOT_TARGET_SET_DENIED'};$snapshot=[ordered]@{};$windows=0
    foreach($entry in $entries){$partition=ConvertTo-ResolvedGuid $entry.PartitionGuid;$relative=[string]$entry.LoaderPath;if(-not$partition-or$relative-notmatch'^\\EFI\\[A-Za-z0-9._ -]+(?:\\[A-Za-z0-9._ -]+)*\.efi$'-or[string]$entry.BootMethod-notin@('WindowsEfiChainload','AndroidExistingEfiChainload','LinuxEfiChainload')){throw 'CURRENT_BOOT_TARGET_IDENTITY_DENIED'};$targetPartition=ConvertTo-ResolvedGuid $TargetAccess.Resolved.PartitionGuid;$loaderAccess=$null;try{$loaderAccess=if($partition-ceq$targetPartition){$TargetAccess}else{Open-PartitionAccess ([guid]$partition)};$trimmed=$relative.TrimStart([char]'\');if(-not(Test-PeX64Loader $loaderAccess.Root $trimmed)){throw 'CURRENT_BOOT_TARGET_MISSING'};$identity=$partition+'|'+$relative.ToLowerInvariant();if($snapshot.Contains($identity)){throw 'CURRENT_BOOT_TARGET_AMBIGUOUS'};$snapshot[$identity]=Get-Hash (Join-Path $loaderAccess.Root $trimmed);if([string]$entry.Family-ceq'Windows'-and[string]$entry.BootMethod-ceq'WindowsEfiChainload'-and$relative-ieq'\EFI\Microsoft\Boot\bootmgfw.efi'){$windows++}}finally{if($null-ne$loaderAccess-and$loaderAccess-ne$TargetAccess){Close-PartitionAccess $loaderAccess}}}
    if($windows-ne1){throw 'WINDOWS_LOADER_RECOVERY_PATH_DENIED'};return [pscustomobject]$snapshot
}
function Test-BootTargetSnapshot([object]$Expected,[object]$Actual){$expectedProperties=@($Expected.PSObject.Properties);$actualProperties=@($Actual.PSObject.Properties);if($expectedProperties.Count-ne$actualProperties.Count){throw 'BOOT_TARGET_POSTWRITE_SET_CHANGED'};foreach($property in $expectedProperties){$match=@($actualProperties|Where-Object{$_.Name-ceq$property.Name});if($match.Count-ne1-or[string]$match[0].Value-cne[string]$property.Value){throw 'BOOT_TARGET_POSTWRITE_IDENTITY_CHANGED'}}}
function Get-WindowsFirmwareEvidence([object]$Core,[byte[]]$BootOrder){$windows=@($Core.BootEntries|Where-Object{[string]$_.Family-ceq'Windows'-and[string]$_.BootMethod-ceq'WindowsEfiChainload'-and[string]$_.LoaderPath-ieq'\EFI\Microsoft\Boot\bootmgfw.efi'});if($windows.Count-ne1){throw 'WINDOWS_FIRMWARE_RECOVERY_ENTRY_DENIED'};$entryMatch=[regex]::Match([string]$windows[0].EntryId,'^firmware:Boot([0-9A-Fa-f]{4})$');if(-not$entryMatch.Success){throw 'WINDOWS_FIRMWARE_RECOVERY_ENTRY_DENIED'};if($BootOrder.Length-lt2-or($BootOrder.Length%2)-ne0){throw 'FIRMWARE_ORDER_MALFORMED'};$number=[Convert]::ToUInt16($entryMatch.Groups[1].Value,16);$present=$false;for($offset=0;$offset-lt$BootOrder.Length;$offset+=2){if([BitConverter]::ToUInt16($BootOrder,$offset)-eq$number){$present=$true;break}};if(-not$present){throw 'WINDOWS_FIRMWARE_RECOVERY_ENTRY_DENIED'};return [pscustomobject]@{EntryNumber=$number;PartitionGuid=ConvertTo-ResolvedGuid $windows[0].PartitionGuid;LoaderPath=[string]$windows[0].LoaderPath}}
function Select-HybridCandidate([object[]]$Candidates,[string]$Role){if($Candidates.Count-eq0){throw ('HYBRID_'+$Role.ToUpperInvariant()+'_TARGET_NOT_FOUND')};if($Candidates.Count-eq1){return $Candidates[0]};Add-Type -AssemblyName System.Windows.Forms;$dialog=[Windows.Forms.Form]::new();$dialog.Text='Confirm SecretoBoot '+$Role+' target';$dialog.Width=820;$dialog.Height=360;$dialog.StartPosition='CenterScreen';$label=[Windows.Forms.Label]::new();$label.Text='More than one validated '+$Role+' target exists. Select one real firmware-backed candidate or cancel.';$label.AutoSize=$true;$label.Left=15;$label.Top=15;$list=[Windows.Forms.ListBox]::new();$list.Left=15;$list.Top=45;$list.Width=770;$list.Height=210;foreach($candidate in $Candidates){$null=$list.Items.Add(('{0} | disk {1}, partition {2} | {3} | {4} bytes | {5} | {6}'-f$candidate.FirmwareDescription,$candidate.DiskNumber,$candidate.PartitionNumber,$candidate.Filesystem,$candidate.SizeBytes,$candidate.PartitionGuid,$candidate.EfiPath))};$ok=[Windows.Forms.Button]::new();$ok.Text='Confirm selected target';$ok.Left=580;$ok.Top=270;$ok.Width=205;$ok.DialogResult=[Windows.Forms.DialogResult]::OK;$dialog.Controls.AddRange(@($label,$list,$ok));$dialog.AcceptButton=$ok;if($dialog.ShowDialog()-ne[Windows.Forms.DialogResult]::OK-or$list.SelectedIndex-lt0){throw 'HYBRID_MANUAL_CONFIRMATION_CANCELLED'};$selected=$Candidates[$list.SelectedIndex];$selected.UserConfirmed=$true;return $selected}
function Confirm-ResolvedFreshInstallPlan([object]$Core){Add-Type -AssemblyName System.Windows.Forms;$lines=[Collections.Generic.List[string]]::new();$lines.Add('The trusted hybrid resolver validated these exact read-only boot targets:');$lines.Add('');foreach($entry in @($Core.BootEntries|Sort-Object Family,DisplayName)){$lines.Add(([string]$entry.Family+': '+[string]$entry.PartitionGuid+' '+[string]$entry.LoaderPath))};$lines.Add('');$lines.Add('Install only EFI\SecretoBoot and create one unordered SecretoBoot firmware entry?');$answer=[Windows.Forms.MessageBox]::Show(($lines-join[Environment]::NewLine),'Confirm resolved SecretoBoot install plan',[Windows.Forms.MessageBoxButtons]::YesNo,[Windows.Forms.MessageBoxIcon]::Warning,[Windows.Forms.MessageBoxDefaultButton]::Button2);if($answer-ne[Windows.Forms.DialogResult]::Yes){throw 'FRESH_INSTALL_RESOLVED_PLAN_CONFIRMATION_DENIED'}}
function Resolve-HybridPlan([object]$Core){
    $script:stage='HybridFirmwareInventory';$firmware=@([SecretoBoot.V9.WindowsFirmware.FirmwareAdapter]::ReadBootInventory());if($firmware.Count-eq0){throw 'FIRMWARE_INVENTORY_EMPTY'};$candidates=@(Resolve-SbHybridFirmwareCandidates -FirmwareEntries $firmware -PartitionInventory @($Core.PartitionInventory));$validated=[Collections.Generic.List[object]]::new()
    foreach($candidate in $candidates){$access=$null;$script:resolverContext=$candidate;try{$access=Open-PartitionAccess ([guid]$candidate.PartitionGuid);$relative=([string]$candidate.EfiPath).TrimStart('\');if(-not(Test-PeX64Loader $access.Root $relative)){continue};if([string]$candidate.Role-ceq'Bliss'){foreach($required in @('kernel','initrd.img')){if(-not(Test-BoundedRegularFile $access.Root $required 1 268435456)){throw 'HYBRID_BLISS_CHAIN_INCOMPLETE'}};foreach($config in @('EFI\BOOT\android.cfg','boot\grub\grub.cfg')){if(-not(Test-BoundedTextConfig $access.Root $config)){throw 'HYBRID_BLISS_CHAIN_INCOMPLETE'}}};$candidate.ValidationState='FirmwareStorageAndLoaderValidated';$validated.Add($candidate)}finally{if($null-ne$access){Close-PartitionAccess $access}}}
    $windows=Select-HybridCandidate @($validated|Where-Object{$_.Role-ceq'Windows'}) 'Windows';$bliss=Select-HybridCandidate @($validated|Where-Object{$_.Role-ceq'Bliss'}) 'Bliss';$targets=@($windows,$bliss)+@($validated|Where-Object{$_.Role-ceq'Linux'});$targets=@($targets|Group-Object{([string]$_.PartitionGuid).ToUpperInvariant()+'|'+([string]$_.EfiPath).ToLowerInvariant()}|ForEach-Object{$_.Group[0]})
    $entries=@($targets|ForEach-Object{$icon=switch([string]$_.Role){'Windows'{'windows.png'};'Bliss'{'bliss.png'};default{'linux.png'}};[pscustomobject][ordered]@{EntryId=('firmware:'+[string]$_.FirmwareIdentifier);DisplayName=[string]$_.DisplayName;Family=if($_.Role-ceq'Bliss'){'Android'}else{[string]$_.Role};BootMethod=[string]$_.BootMethod;PartitionGuid=[string]$_.PartitionGuid;DiskGuid=[string]$_.DiskGuid;LoaderPath=[string]$_.EfiPath;IconPath=('\EFI\SecretoBoot\themes\SecretoBootV9\icons\'+$icon);Evidence='Validated existing firmware entry + GPT partition + bounded EFI loader';UserConfirmed=[bool]$_.UserConfirmed;BootReady=$true}})
    $Core.TargetEspPartitionGuid=[string]$windows.PartitionGuid;$Core.TargetEspDiskGuid=[string]$windows.DiskGuid;$Core.BootEntries=$entries;$Core.RefindConfig=New-SbHybridRefindConfig $targets;$Core|Add-Member -NotePropertyName HybridResolutionCompleted -NotePropertyValue $true -Force;return $Core
}
function Read-Ownership {
    if(-not[IO.File]::Exists($ownershipStatePath)){throw 'OWNERSHIP_STATE_MISSING'}
    try{$m=Get-Content $ownershipStatePath -Raw|ConvertFrom-Json}catch{throw 'OWNERSHIP_STATE_JSON_INVALID'}
    if('SchemaVersion'-notin$m.PSObject.Properties.Name-or[string]$m.SchemaVersion-cne'v9-ownership-manifest-1'){throw 'OWNERSHIP_SCHEMA_VERSION_UNSUPPORTED'}
    foreach($name in 'OwnershipVerified','Revision','TargetEspPartitionGuid','InstalledFiles','FirmwareEntryName','FirmwareEntryNumber','FirmwareLoadOptionBase64','BootOrderChangedByMakeDefault'){if($name-notin$m.PSObject.Properties.Name){throw 'OWNERSHIP_REQUIRED_FIELD_MISSING'}}
    if($m.OwnershipVerified-ne$true){throw 'OWNERSHIP_STATE_DENIED'}
    if([string]$m.Revision-notin$supportedOwnershipRevisions){throw 'OWNERSHIP_STATE_MIGRATION_REQUIRED'}
    if($null-eq$m.InstalledFiles-or$null-eq$m.InstalledFiles.PSObject-or@($m.InstalledFiles.PSObject.Properties).Count-eq0){throw 'OWNERSHIP_FIELD_TYPE_INVALID'}
    return $m
}
function Get-InstalledFirmwareIdentity([object]$Manifest){
    if($null-eq$Manifest){throw 'OWNERSHIP_STATE_MISSING'}
    foreach($name in 'TargetEspPartitionGuid','FirmwareEntryName','FirmwareEntryNumber','FirmwareLoadOptionBase64','InstalledFiles'){if($name-notin$Manifest.PSObject.Properties.Name){throw 'OWNERSHIP_STATE_REQUIRED_FIELD_MISSING'}}
    $partition=ConvertTo-ResolvedGuid $Manifest.TargetEspPartitionGuid;if(-not$partition){throw 'OWNERSHIP_TARGET_PARTITION_IDENTITY_INVALID'}
    $number=0;try{$number=[uint16]$Manifest.FirmwareEntryNumber}catch{throw 'OWNERSHIP_FIRMWARE_ENTRY_NUMBER_INVALID'}
    $entryName=[string]$Manifest.FirmwareEntryName;if($entryName-cne('Boot'+$number.ToString('X4'))){throw 'OWNERSHIP_FIRMWARE_ENTRY_NUMBER_MISMATCH'}
    try{$loadOption=[Convert]::FromBase64String([string]$Manifest.FirmwareLoadOptionBase64)}catch{throw 'OWNERSHIP_FIRMWARE_LOAD_OPTION_INVALID'}
    if($loadOption.Length-eq0){throw 'OWNERSHIP_FIRMWARE_LOAD_OPTION_INVALID'}
    return [pscustomobject]@{PartitionGuid=[guid]$partition;EntryNumber=$number;EntryName=$entryName;LoadOption=[byte[]]$loadOption}
}
function Get-InstalledIdentityDigest([object]$Manifest,[object]$Identity){$refind=[string]$Manifest.InstalledFiles.'refind_x64.efi';if($refind-notmatch'^[0-9a-f]{64}$'){throw 'OWNED_LOADER_HASH_MISMATCH'};$canonical=([string]$Identity.EntryName).ToUpperInvariant()+'|'+([string]$Identity.PartitionGuid).ToUpperInvariant()+'|\EFI\SecretoBoot\refind_x64.efi|'+$refind+'|'+[string]$Manifest.Revision;return [Convert]::ToHexString([Security.Cryptography.SHA256]::HashData([Text.Encoding]::UTF8.GetBytes($canonical))).ToLowerInvariant()}
function Get-CanonicalInstalledState([object]$Manifest,[object]$Identity,[object]$Access,[string]$OwnedRoot,[object]$Core,[bool]$AllowMissing){
    $script:stage='CanonicalOwnershipValidation';Test-OwnedFiles $Manifest $OwnedRoot;Test-EfiOwnershipManifest $Manifest $OwnedRoot
    $firmwareStatus='Verified';$firmware=$null;$script:stage='CanonicalFirmwareInventory';try{$firmware=[SecretoBoot.V9.WindowsFirmware.FirmwareAdapter]::VerifyInstalledOwnedEntry([uint16]$Identity.EntryNumber,[string]$Identity.EntryName,[byte[]]$Identity.LoadOption,[guid]$Identity.PartitionGuid)}catch{$reason=Get-SafeReason $_;if($AllowMissing-and$reason-ceq'OWNED_FIRMWARE_ENTRY_MISSING'){$firmwareStatus='Missing'}else{throw $reason}}
    $script:stage='CanonicalBootStateRead';$bootOrder=[SecretoBoot.V9.WindowsFirmware.FirmwareAdapter]::ReadVariable('BootOrder');$bootNext=[SecretoBoot.V9.WindowsFirmware.FirmwareAdapter]::ReadVariable('BootNext')
    $targets=$null;$windows=$null;if($null-ne$Core-and$firmwareStatus-ceq'Verified'){$script:stage='CanonicalBootTargetVerification';$targets=Get-CurrentBootTargetSnapshot $Core $Access;$script:stage='CanonicalWindowsRecoveryVerification';$windows=Get-WindowsFirmwareEvidence $Core $bootOrder}
    return [pscustomobject][ordered]@{Manifest=$Manifest;Identity=$Identity;FirmwareStatus=$firmwareStatus;FirmwareEntry=$firmware;BootOrder=[byte[]]$bootOrder;BootNext=[byte[]]$bootNext;BootTargets=$targets;WindowsRecovery=$windows;InstalledIdentityDigest=Get-InstalledIdentityDigest $Manifest $Identity;ThemeVerified=('ThemeRevision'-in$Manifest.PSObject.Properties.Name-and[string]$Manifest.ThemeRevision-ceq'FinalRelease.1'-and'ThemeDeployment'-in$Manifest.PSObject.Properties.Name-and[string]$Manifest.ThemeDeployment-ceq'MATCH');StateFreshness='Current'}
}
function ConvertTo-SnapshotGuid([object]$Value){$parsed=[guid]::Empty;if(-not[guid]::TryParse([string]$Value,[ref]$parsed)-or$parsed-eq[guid]::Empty){throw 'SNAPSHOT_FIELD_TYPE_INVALID'};$parsed.ToString('D').ToUpperInvariant()}
function ConvertTo-SnapshotEfiPath([object]$Value){$path=([string]$Value).Replace('/','\');if(-not$path.StartsWith('\')){$path='\'+$path};if($path-notmatch'^\\EFI\\[A-Za-z0-9._ -]+(?:\\[A-Za-z0-9._ -]+)*\.efi$'){throw 'SNAPSHOT_FIELD_TYPE_INVALID'};$path.ToLowerInvariant()}
function ConvertTo-SnapshotBootName([object]$Value){$number=0;if(-not[int]::TryParse([string]$Value,[ref]$number)-or$number-lt0-or$number-gt65535){throw 'SNAPSHOT_FIELD_TYPE_INVALID'};'Boot'+$number.ToString('X4')}
function Test-PersistentDefaultSnapshotReadback([object]$Expected,[object]$Actual){
    if([string]$Actual.SchemaVersion-cne'v9-persistent-default-snapshot-1'){throw 'SNAPSHOT_SCHEMA_INVALID'}
    try{$actualOrder=[Convert]::FromBase64String([string]$Actual.OriginalBootOrderBase64)}catch{throw 'SNAPSHOT_BOOTORDER_INVALID'};if([Convert]::ToBase64String($actualOrder)-cne[string]$Expected.OriginalBootOrderBase64){throw 'SNAPSHOT_BOOTORDER_INVALID'}
    if([int]$Actual.SecretoBootEntryNumber-ne[int]$Expected.SecretoBootEntryNumber-or[string]$Actual.SecretoBootEntryName-cne(ConvertTo-SnapshotBootName $Expected.SecretoBootEntryNumber)-or(ConvertTo-SnapshotGuid $Actual.SecretoBootPartitionGuid)-cne[string]$Expected.SecretoBootPartitionGuid-or(ConvertTo-SnapshotEfiPath $Actual.SecretoBootLoaderPath)-cne[string]$Expected.SecretoBootLoaderPath){throw 'SNAPSHOT_OWNED_ENTRY_INVALID'}
    if([int]$Actual.WindowsEntryNumber-ne[int]$Expected.WindowsEntryNumber-or(ConvertTo-SnapshotGuid $Actual.WindowsPartitionGuid)-cne[string]$Expected.WindowsPartitionGuid-or(ConvertTo-SnapshotEfiPath $Actual.WindowsLoaderPath)-cne[string]$Expected.WindowsLoaderPath){throw 'SNAPSHOT_WINDOWS_RECOVERY_INVALID'}
    if([string]$Actual.InstalledIdentityDigest-cne[string]$Expected.InstalledIdentityDigest){throw 'SNAPSHOT_IDENTITY_DIGEST_MISMATCH'}
    if([string]$Actual.OwnershipStateSha256-cne[string]$Expected.OwnershipStateSha256-or[string]$Actual.OwnershipRevision-cne[string]$Expected.OwnershipRevision){throw 'SNAPSHOT_OWNERSHIP_HASH_MISMATCH'}
    if([bool]$Actual.PreviousPersistentDefault-ne[bool]$Expected.PreviousPersistentDefault){throw 'SNAPSHOT_READBACK_NORMALIZATION_MISMATCH'}
    return $true
}
function New-PersistentDefaultSnapshot([object]$Canonical){
    $script:stage='PersistentDefaultBootOrderCapture';if($Canonical.BootOrder.Length-lt2-or($Canonical.BootOrder.Length%2)-ne0){throw 'BOOT_ORDER_CAPTURE_FAILED'}
    $script:stage='PersistentDefaultOwnedEntryCapture';if($Canonical.FirmwareStatus-cne'Verified'-or$null-eq$Canonical.FirmwareEntry){throw 'OWNED_ENTRY_CAPTURE_FAILED'}
    $script:stage='PersistentDefaultWindowsRecoveryCapture';if($null-eq$Canonical.WindowsRecovery){throw 'WINDOWS_RECOVERY_CAPTURE_FAILED'}
    $script:stage='PersistentDefaultOwnershipStateLoad';if(-not[IO.File]::Exists($ownershipStatePath)){throw 'OWNERSHIP_STATE_INVALID'};$ownershipHash=Get-Hash $ownershipStatePath
    $snapshot=[pscustomobject][ordered]@{SchemaVersion='v9-persistent-default-snapshot-1';Revision=$revision;CapturedUtc=[DateTime]::UtcNow.ToString('o');OriginalBootOrderBase64=[Convert]::ToBase64String([byte[]]$Canonical.BootOrder);SecretoBootEntryName=ConvertTo-SnapshotBootName $Canonical.Identity.EntryNumber;SecretoBootEntryNumber=[int]$Canonical.Identity.EntryNumber;SecretoBootPartitionGuid=ConvertTo-SnapshotGuid $Canonical.Identity.PartitionGuid;SecretoBootLoaderPath=ConvertTo-SnapshotEfiPath '\EFI\SecretoBoot\refind_x64.efi';WindowsEntryNumber=[int]$Canonical.WindowsRecovery.EntryNumber;WindowsPartitionGuid=ConvertTo-SnapshotGuid $Canonical.WindowsRecovery.PartitionGuid;WindowsLoaderPath=ConvertTo-SnapshotEfiPath $Canonical.WindowsRecovery.LoaderPath;InstalledIdentityDigest=([string]$Canonical.InstalledIdentityDigest).ToLowerInvariant();OwnershipRevision=[string]$Canonical.Manifest.Revision;OwnershipStateSha256=$ownershipHash.ToLowerInvariant();PreviousPersistentDefault=[bool]$Canonical.Manifest.BootOrderChangedByMakeDefault}
    $script:stage='PersistentDefaultSnapshotSerialize';try{$serialized=Get-StateText $snapshot;if([string]::IsNullOrWhiteSpace($serialized)){throw 'SNAPSHOT_SERIALIZATION_FAILED'}}catch{throw 'SNAPSHOT_SERIALIZATION_FAILED'}
    $script:stage='PersistentDefaultSnapshotPersist';try{Write-State $snapshot $persistentSnapshotPath}catch{throw 'SNAPSHOT_WRITE_FAILED'}
    $script:stage='PersistentDefaultSnapshotReadback';try{$read=Get-Content $persistentSnapshotPath -Raw|ConvertFrom-Json}catch{throw 'SNAPSHOT_READBACK_FAILED'}
    $script:stage='PersistentDefaultSnapshotValidation';$null=Test-PersistentDefaultSnapshotReadback $snapshot $read;return $read
}
function Get-PersistentDefaultRollbackContext([object]$Canonical,[string]$OwnedRoot){
    $script:stage='PersistentDefaultOwnershipStateLoad'
    $efiPath=Join-Path $OwnedRoot 'ownership-manifest.json';if(-not[IO.File]::Exists($efiPath)-or-not[IO.File]::Exists($ownershipStatePath)){throw 'OWNERSHIP_REQUIRED_FIELD_MISSING'}
    try{$efiText=[IO.File]::ReadAllText($efiPath);$stateText=[IO.File]::ReadAllText($ownershipStatePath);$efiHash=Get-Hash $efiPath;$stateHash=Get-Hash $ownershipStatePath}catch{throw 'OWNERSHIP_STATE_READ_FAILED'}
    if($efiHash-cne$stateHash){throw 'OWNERSHIP_HASH_MISMATCH'}
    try{$efiManifest=$efiText|ConvertFrom-Json;$stateManifest=$stateText|ConvertFrom-Json}catch{throw 'OWNERSHIP_STATE_JSON_INVALID'}
    foreach($name in 'SchemaVersion','Revision','TargetEspPartitionGuid','FirmwareEntryName','FirmwareEntryNumber'){
        if($name-notin$efiManifest.PSObject.Properties.Name-or$name-notin$stateManifest.PSObject.Properties.Name-or$name-notin$Canonical.Manifest.PSObject.Properties.Name){throw 'OWNERSHIP_REQUIRED_FIELD_MISSING'}
    }
    if([string]$efiManifest.SchemaVersion-cne[string]$stateManifest.SchemaVersion-or[string]$efiManifest.SchemaVersion-cne[string]$Canonical.Manifest.SchemaVersion-or
       [string]$efiManifest.Revision-cne[string]$stateManifest.Revision-or[string]$efiManifest.Revision-cne[string]$Canonical.Manifest.Revision-or
       [string]$efiManifest.TargetEspPartitionGuid-cne[string]$stateManifest.TargetEspPartitionGuid-or[string]$efiManifest.TargetEspPartitionGuid-cne[string]$Canonical.Manifest.TargetEspPartitionGuid-or
       [string]$efiManifest.FirmwareEntryName-cne[string]$stateManifest.FirmwareEntryName-or[string]$efiManifest.FirmwareEntryName-cne[string]$Canonical.Manifest.FirmwareEntryName-or
       [int]$efiManifest.FirmwareEntryNumber-ne[int]$stateManifest.FirmwareEntryNumber-or[int]$efiManifest.FirmwareEntryNumber-ne[int]$Canonical.Manifest.FirmwareEntryNumber){throw 'OWNERSHIP_IDENTITY_MISMATCH'}
    $snapshotText=$null;$snapshotDisposition='NotPresent'
    if([IO.File]::Exists($persistentSnapshotPath)){
        $script:stage='PersistentDefaultHistoricalSnapshotCompatibility'
        try{$candidateText=[IO.File]::ReadAllText($persistentSnapshotPath);$candidate=$candidateText|ConvertFrom-Json;if([string]$candidate.SchemaVersion-ceq'v9-persistent-default-snapshot-1'-and[string]$candidate.InstalledIdentityDigest-ceq[string]$Canonical.InstalledIdentityDigest-and[int]$candidate.SecretoBootEntryNumber-eq[int]$Canonical.Identity.EntryNumber-and[string]$candidate.SecretoBootPartitionGuid-ceq[string]$Canonical.Identity.PartitionGuid){$snapshotText=$candidateText;$snapshotDisposition='PreservedCurrent'}else{$snapshotDisposition='DiscardedStale'}}catch{$snapshotDisposition='DiscardedInvalid'}
    }
    return [pscustomobject]@{EfiManifestText=$efiText;StateManifestText=$stateText;SnapshotText=$snapshotText;SnapshotDisposition=$snapshotDisposition}
}
function Test-CurrentOneTimeVerification([object]$Canonical){if(-not[IO.File]::Exists($statePath)){throw 'CURRENT_ONE_TIME_TEST_REQUIRED'};try{$test=Get-Content $statePath -Raw|ConvertFrom-Json}catch{throw 'CURRENT_ONE_TIME_TEST_REQUIRED'};if($test.BootNextVerified-ne$true-or[string]$test.TestInstalledIdentityDigest-cne[string]$Canonical.InstalledIdentityDigest-or[int]$test.TestFirmwareEntryNumber-ne[int]$Canonical.Identity.EntryNumber-or[string]$test.TestPartitionGuid-cne[string]$Canonical.Identity.PartitionGuid-or[string]$test.TestRefindSha256-cne[string]$Canonical.Manifest.InstalledFiles.'refind_x64.efi'-or[string]$test.TestInstalledRevision-cne[string]$Canonical.Manifest.Revision){throw 'CURRENT_ONE_TIME_TEST_STALE'};if($Canonical.BootNext.Length-ne0){throw 'CURRENT_ONE_TIME_TEST_NOT_CONSUMED'};return $true}
function Get-CompatibilityBootOrderFirst([object]$Value){try{$bytes=[byte[]]@($Value)}catch{throw 'COMPATIBILITY_STATE_INVALID'};if($bytes.Length-lt2-or($bytes.Length%2)-ne0){throw 'COMPATIBILITY_STATE_INVALID'};return [uint16](([uint16]$bytes[0])-bor(([uint16]$bytes[1])-shl 8))}
function Get-CurrentFirmwareDisplayOrderFirstIdentifier {
    $exe=Join-Path $env:SystemRoot 'System32\bcdedit.exe'
    if(-not[IO.File]::Exists($exe)){throw 'WINDOWS_FIRMWARE_MANAGER_UNAVAILABLE'}
    try{
        $captured=@(& $exe /enum '{fwbootmgr}' 2>&1)
        $exitCode=[int]$LASTEXITCODE
    }catch{
        $script:resolverDiagnostic=('Command='+$exe+' /enum {fwbootmgr}; DirectInvocationException='+([string]$_.Exception.Message -replace'[\r\n\t]+',' '))
        throw 'WINDOWS_FIRMWARE_INVENTORY_QUERY_FAILED'
    }
    $text=(($captured|ForEach-Object{[string]$_}) -join [Environment]::NewLine)
    $compact=($text-replace'[\r\n\t]+',' ').Trim();if($compact.Length-gt700){$compact=$compact.Substring(0,700)}
    if($exitCode-ne0){$script:resolverDiagnostic=('Command='+$exe+' /enum {fwbootmgr}; ExitCode='+$exitCode+'; Output='+$compact);throw 'WINDOWS_FIRMWARE_INVENTORY_QUERY_FAILED'}
    foreach($item in $captured){
        $line=[string]$item
        $m=[regex]::Match($line,'^\s*displayorder\s+(\{[^}]+\})\s*$',[Text.RegularExpressions.RegexOptions]::IgnoreCase)
        if($m.Success){
            $identifier=[string]$m.Groups[1].Value
            $script:resolverDiagnostic=('Command='+$exe+' /enum {fwbootmgr}; ExitCode=0; FirstDisplayOrder='+$identifier+'; Output='+$compact)
            return $identifier
        }
    }
    $script:resolverDiagnostic=('Command='+$exe+' /enum {fwbootmgr}; ExitCode=0; FirstDisplayOrder=MISSING; Output='+$compact)
    throw 'WINDOWS_FIRMWARE_DISPLAYORDER_MISSING'
}
function Test-WindowsFirstCompatibilityPreflight([object]$Canonical,[object]$Manifest,[object]$Core){
    $script:stage='WindowsFirstCompatibilityIdentityVerification';try{$null=Test-CurrentOneTimeVerification $Canonical}catch{$reason=Get-SafeReason $_;if($reason-ceq'UNEXPECTED_OPERATION_FAILURE'){throw 'COMPATIBILITY_IDENTITY_MISMATCH'};throw $reason}
